// The registry archive already contains bindings generated by the release
// build from its pinned proto revision. A consumer only copies those Rust
// files; no compiler, submodule, network request or source-mode fallback runs.
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let root = std::path::PathBuf::from(
        std::env::var_os("CARGO_MANIFEST_DIR").ok_or("missing manifest directory")?,
    );
    let out =
        std::path::PathBuf::from(std::env::var_os("OUT_DIR").ok_or("missing output directory")?);
    let bindings = root.join("bindings");
    println!("cargo:rerun-if-changed={}", bindings.display());
    for name in std::fs::read_to_string(bindings.join("files.txt"))?.lines() {
        // The list is release-generated; reject any escape even if an archive
        // was subsequently edited by a consumer.
        if name.is_empty() || name.contains('/') || name.contains('\\') || !name.ends_with(".rs") {
            return Err("invalid prepared binding name".into());
        }
        std::fs::copy(bindings.join(name), out.join(name))?;
    }
    Ok(())
}
